/* Only loaded when the page is opened straight from disk (file://).
   Chrome treats local files as cross-origin, so WebGL may not read their
   pixels; data: URLs are always readable. */
window.__OFFLINE = {
  sculpt: 'data:image/webp;base64,',
  sculptMobile: 'data:image/webp;base64,',
  logo: 'data:image/webp;base64,'
};
